import sys, json, time, random
import numpy as np

def main():
    if len(sys.argv) < 3:
        return
    start_time = time.time()
    instance_path = sys.argv[1]
    time_limit = float(sys.argv[2])
    if "QAP_TIME_LIMIT_S" in sys.argv:
        env_limit = float(sys.argv[2])
        time_limit = min(time_limit, env_limit)
    else:
        env_limit = float(sys.argv[2])
        time_limit = min(time_limit, env_limit)
    budget = time_limit - (time.time() - start_time)
    if budget <= 0:
        return
    with open(instance_path) as f:
        data = json.load(f)
    n = data["n"]
    A = np.array(data["A"], dtype=np.int64)
    B = np.array(data["B"], dtype=np.int64)
    best_cost = float('inf')
    best_perm = None
    start = time.time()
    while time.time() - start < budget:
        perm = list(range(n))
        random.shuffle(perm)
        cur_cost = 0
        for i in range(n):
            for j in range(i+1, n):
                cur_cost += A[i, j] * B[perm[i], perm[j]]
                cur_cost += A[j, i] * B[perm[j], perm[i]]
        if cur_cost < best_cost:
            best_cost = cur_cost
            best_perm = perm[:]
        improved = True
        while improved:
            improved = False
            for i in range(n):
                for j in range(i+1, n):
                    new_perm = perm[:]
                    new_perm[i], new_perm[j] = new_perm[j], new_perm[i]
                    new_cost = 0
                    for k in range(n):
                        for l in range(k+1, n):
                            new_cost += A[k, l] * B[new_perm[k], new_perm[l]]
                            new_cost += A[l, k] * B[new_perm[l], new_perm[k]]
                    if new_cost < cur_cost:
                        cur_cost = new_cost
                        perm = new_perm
                        improved = True
                        break
                if improved:
                    break
        if time.time() - start >= budget:
            break
        T = max(1e-3, 1.0 - (time.time() - start) / budget)
        for i in range(n):
            for j in range(i+1, n):
                delta = 0
                for k in range(n):
                    delta += A[i, k] * (B[perm[i], perm[k]] - B[perm[j], perm[k]])
                    delta += A[k, i] * (B[perm[k], perm[i]] - B[perm[k], perm[j]])
                    delta += A[j, k] * (B[perm[j], perm[k]] - B[perm[i], perm[k]])
                    delta += A[k, j] * (B[perm[k], perm[j]] - B[perm[k], perm[i]])
                if random.random() < np.exp(-delta * T / (1e-6 + best_cost)):
                    perm[i], perm[j] = perm[j], perm[i]
                    cur_cost += delta
                    improved = True
        if time.time() - start >= budget:
            break
    if best_perm is None:
        best_perm = list(range(n))
    out = " ".join(str(x+1) for x in best_perm)
    print(f"PERMUTATION: {out}")

if __name__ == "__main__":
    main()
